import sys

def get_reversals(s):
    n = len(s)
    result = [0] * n
    s = list(s)

    for i in range(n):
        if s[i] == 'b':
            # Find the leftmost 'a' to swap with
            for j in range(i):
                if s[j] == 'a':
                    # Swap 'a' and 'b'
                    s[i], s[j] = s[j], s[i]
                    result[i] = 1
                    break

    return result

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().strip()
    result = get_reversals(data)
    print(" ".join(map(str, result)))

import sys

def get_reverse_operations(s):
    n = len(s)
    result = [0] * n
    s = list(s)

    for i in range(n):
        if s[i] == 'b':
            # Find the leftmost 'a' to swap with
            for j in range(i):
                if s[j] == 'a':
                    # Reverse the prefix from 0 to i
                    result[i] = 1
                    s[:i+1] = s[:i+1][::-1]
                    break

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().strip()
    result = get_reverse_operations(data)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
